-- IF NOT EXISTS also adopts the schema deployed before Flyway was introduced.
CREATE TABLE IF NOT EXISTS cities (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS stores (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, city_id BIGINT NOT NULL REFERENCES cities(id), address VARCHAR(200), created_at TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(200) NOT NULL, category_id BIGINT REFERENCES categories(id), unit VARCHAR(20) NOT NULL, created_at TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS product_prices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id), store_id BIGINT NOT NULL REFERENCES stores(id), price NUMERIC(10,2) NOT NULL, price_date DATE NOT NULL, created_at TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS product_packages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(500), icon VARCHAR(50), type VARCHAR(50) NOT NULL, created_at TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS package_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, package_id BIGINT NOT NULL REFERENCES product_packages(id), product_id BIGINT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS store_promotions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, store_id BIGINT NOT NULL REFERENCES stores(id), category_id BIGINT REFERENCES categories(id), title VARCHAR(200) NOT NULL, description VARCHAR(500), discount_percent INTEGER, day_of_week VARCHAR(20), time_from TIME(6), time_to TIME(6), valid_from DATE NOT NULL, valid_to DATE NOT NULL, active BOOLEAN NOT NULL, created_at TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS app_users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL);
